import torch
import torch.nn as nn

class MLP(nn.Module):
    def __init__(self, input_dim, num_classes, hidden_dims=(128, 64), dropout=0.2):
        super().__init__()
        layers, previous_dim = [], input_dim
        for hidden_dim in hidden_dims:
            layers += [nn.Linear(previous_dim, hidden_dim), nn.ReLU(), nn.Dropout(dropout)]
            previous_dim = hidden_dim
        layers.append(nn.Linear(previous_dim, num_classes))
        self.network = nn.Sequential(*layers)
    def forward(self, x):
        return self.network(x)

